begin;

do $$
declare
  v_sector uuid;
  v_category uuid;
  v_body jsonb;
  v_text text;
  v_id uuid;
begin
  select id into v_sector from public.sectors where slug='addiction-recovery';
  select id into v_category from public.categories where slug='addiction-harm-reduction' and sector_id=v_sector;
  if v_sector is null or v_category is null then raise exception 'harm reduction taxonomy missing'; end if;

  v_body := jsonb_build_object('blocks', jsonb_build_array(
    jsonb_build_object('type','paragraph','text','خفض الضرر في اضطرابات استخدام المواد هو نهج صحة عامة يهدف إلى تقليل الوفاة والمرض والعدوى والإصابات والعواقب الاجتماعية القابلة للمنع، سواء كان الشخص مستعدًا للتوقف الكامل الآن أم لم يكن. لا يتعارض هذا النهج مع العلاج أو التعافي، ولا يساوي تشجيع الاستخدام؛ بل يحاول تقليل الضرر الفوري وبناء صلة مستمرة بالخدمات حتى تصبح خيارات العلاج والحماية أكثر واقعية. نجاحه يقاس بنتائج ملموسة مثل انخفاض الجرعات الزائدة والعدوى وتحسن الوصول إلى العلاج واستمراريته، وليس بقدرة البرنامج على فرض هدف واحد على جميع الأشخاص.'),

    jsonb_build_object('type','heading','level',2,'text','1. ما خفض الضرر وما الذي لا يعنيه؟'),
    jsonb_build_object('type','paragraph','text','ينطلق خفض الضرر من حقيقة سريرية ومجتمعية بسيطة: المخاطر لا تنتظر اكتمال الدافعية أو توفر سرير علاجي أو استقرار السكن. الشخص الذي يواجه خطر جرعة زائدة أو عدوى أو عنف أو انقطاع عن الدواء يحتاج تدخلًا يقلل الخطر الحالي، ثم فرصة للانتقال إلى رعاية أوسع. لذلك يمكن أن تشمل منظومة خفض الضرر التثقيف الصحي، الوصول إلى خدمات الجرعة الزائدة، الفحص والعلاج للعدوى، العلاج الفعال لاضطراب استخدام الأفيونات، خدمات منخفضة العتبة، دعم الأقران، الربط بالرعاية النفسية والجسدية، ومساندة السكن والحقوق عندما تؤثر في السلامة. لا توجد ضرورة لجعل الشخص يثبت استحقاقه للرعاية عبر الامتناع أولًا.'),
    jsonb_build_object('type','paragraph','text','لا يعني خفض الضرر أن كل سلوك يمكن جعله آمنًا، ولا أنه بديل عن العلاج المتخصص عندما توجد حاجة إليه، ولا أنه يتجاهل هدف الامتناع لمن يريده. بعض المخاطر لا يمكن إزالتها بالكامل، وبعض حالات التسمم والانسحاب تحتاج رعاية طبية، وبعض الأشخاص يريدون التوقف الكامل ويجب دعمهم في ذلك. القيمة الأساسية هي توسيع الخيارات بدل جعل الرعاية ثنائية: إما امتناع كامل أو لا مساعدة. عندما يكون الوصول متدرجًا، يستطيع النظام حماية الحياة اليوم والعمل على أهداف التعافي غدًا.'),

    jsonb_build_object('type','heading','level',2,'text','2. ترتيب المخاطر: ما الذي يجب أن يسبق غيره؟'),
    jsonb_build_object('type','paragraph','text','من المفيد ترتيب الخطة حسب احتمال الضرر وشدته وقابليته للتعديل. يبدأ التقييم بمخاطر التسمم الحاد والجرعة الزائدة وفقدان الوعي وصعوبة التنفس، ثم الانسحاب الذي قد يكون خطيرًا لبعض المواد، ثم العدوى والإصابات والأمراض المصاحبة، ثم مخاطر العنف والاستغلال والتشرد والحبس والانقطاع عن العلاج. بعد ذلك تُبنى أهداف أوسع تتعلق بالنوم والمزاج والعمل والعلاقات والوظيفة اليومية. هذا الترتيب لا يقلل من أهمية التعافي طويل المدى؛ بل يمنع فقدان الشخص قبل أن تصل الخطة إلى تلك المرحلة.'),
    jsonb_build_object('type','paragraph','text','استخدام مواد متعددة يرفع تعقيد الخطر. معرفة الاسم الذي يفضله الشخص لمادة معينة لا تكفي دائمًا، لأن المحتوى الفعلي قد يختلف ولأن الكحول أو المهدئات أو الأفيونات أو المنبهات يمكن أن تتداخل في التأثير والخطر. لذلك تسأل الخدمة عن الصورة الكاملة دون لوم، وعن الأدوية الموصوفة والحالات الطبية والنوم والصحة النفسية وتاريخ الجرعات الزائدة. الهدف ليس التحقيق في السلوك، بل اكتشاف ما يغير قرار السلامة والإحالة. كلما كانت المقابلة وصمية أو عقابية، زاد احتمال إخفاء معلومات مهمة.'),

    jsonb_build_object('type','heading','level',2,'text','3. الوقاية من الجرعة الزائدة والاستجابة المجتمعية'),
    jsonb_build_object('type','heading','level',3,'text','التعرف إلى الخطر دون تحويل الصفحة إلى بروتوكول منزلي'),
    jsonb_build_object('type','paragraph','text','الاشتباه بجرعة زائدة يرتفع عند وجود فقدان استجابة، اضطراب واضح في الوعي أو التنفس، تغير شديد مفاجئ، أو سياق معروف لاستخدام مادة قد تسبب تثبيط التنفس. في هذه الحالات الأولوية هي طلب خدمات الطوارئ المحلية واتّباع تعليمات الجهات المؤهلة. لا ينبغي انتظار التأكد من نوع المادة قبل طلب المساعدة، لأن التأخير قد يكون حاسمًا. عندما تكون برامج النالوكسون متاحة قانونيًا ومحليًا، توصي منظمة الصحة العالمية بأن يتمكن الأشخاص المحتمل أن يشهدوا جرعة زائدة أفيونية، بمن فيهم أفراد الأسرة والأصدقاء والأقران، من الوصول إليه والتدرب على استخدامه ضمن برنامج منظم. يبقى ذلك استجابة إسعافية مؤقتة وليس بديلًا عن الرعاية الطبية.'),
    jsonb_build_object('type','paragraph','text','الوقاية من الجرعة الزائدة لا تبدأ عند لحظة الطوارئ فقط. تاريخ جرعة زائدة سابقة، الخروج من فترة امتناع أو احتجاز أو علاج داخلي، فقدان التحمل، انقطاع العلاج الفعال لاضطراب استخدام الأفيونات، استخدام مواد متعددة، وعدم استقرار السكن كلها عوامل تجعل الانتقال والمتابعة أكثر أهمية. الخدمة الجيدة تلتقط هذه اللحظات وتربط الشخص بموعد قريب وعلاج مناسب وتثقيف ومساندة، بدل الاكتفاء بعلاج الحدث الحاد ثم إغلاق الملف.'),

    jsonb_build_object('type','heading','level',3,'text','العلاج الفعال للأفيونات جزء من خفض الوفيات'),
    jsonb_build_object('type','paragraph','text','العلاج الصياني بناهضات الأفيون مثل الميثادون والبوبرينورفين، عندما يقدمه مختصون ضمن ممارسة طبية منظمة، ليس مجرد مكون علاجي منفصل عن خفض الضرر. تؤكد منظمة الصحة العالمية قوة الأدلة على فائدته في اضطراب الاعتماد على الأفيونات وعلى دوره في تقليل أضرار ونتائج صحية خطرة وتحسين الاستبقاء. لذلك فإن إتاحة العلاج واستمراريته، وتجنب الانقطاع غير الضروري، ومعالجة الحواجز التنظيمية والوصمية، تدخلات سلامة أيضًا. تحديد الدواء والصيغة والمتابعة قرار سريري فردي ولا يُستبدل بقائمة تعليمات عامة.'),

    jsonb_build_object('type','heading','level',2,'text','4. الوقاية من HIV والتهاب الكبد والعدوى المرتبطة بالحقن'),
    jsonb_build_object('type','paragraph','text','الأشخاص الذين يحقنون المواد معرضون بصورة غير متكافئة لفيروس نقص المناعة البشري والتهاب الكبد الفيروسي والالتهابات الجلدية والأنسجة الرخوة وغيرها من المضاعفات. أصدرت منظمة الصحة العالمية في 2026 دليلًا تشغيليًا حديثًا لبرامج الإبر والمحاقن ضمن استجابة شاملة لخفض الضرر، مع التركيز على التخطيط والتغطية والاندماج مع الخدمات الصحية والاجتماعية والقياس والاستدامة والقيادة المجتمعية والحقوق. هذه الصفحة لا تشرح تقنيات الحقن أو تفاصيل تشغيل أدوات الاستخدام؛ ما يهم المستخدم هنا هو معرفة أن الوقاية الفعالة تتطلب خدمات صحية منخفضة الحواجز ومسارات فحص وعلاج وربطًا مستمرًا بالرعاية.'),
    jsonb_build_object('type','heading','level',3,'text','الفحص والعلاج واللقاحات كمسار واحد'),
    jsonb_build_object('type','paragraph','text','خفض خطر العدوى لا يكتمل بإجراء وقائي منفرد. ينبغي أن تكون لدى الخدمات قدرة على ربط الشخص بفحص HIV والتهاب الكبد B وC وفق الإرشادات المحلية، وتقييم الأعراض والإصابات، وإتاحة العلاج عند التشخيص، ومراجعة التطعيمات المناسبة مثل التهاب الكبد B عندما تكون مطلوبة، مع الحفاظ على السرية والقبول المستنير. أحدث إرشادات منظمة الصحة العالمية المجمعة لالتهاب الكبد في 2026 تؤكد التبسيط واللامركزية والربط بالرعاية وإدماج خدمات خفض الضرر ضمن مسار الوقاية والاختبار والعلاج.'),
    jsonb_build_object('type','paragraph','text','من المهم أيضًا ألا تصبح نتيجة الفحص بوابة للعقوبة أو الإقصاء. الشخص الذي يتلقى نتيجة إيجابية يحتاج مسارًا واضحًا إلى العلاج والمتابعة، والشخص ذو النتيجة السلبية يحتاج وقاية مستمرة تناسب مستوى الخطر. عندما تكون الخدمات موزعة بين عيادات لا تتواصل، قد يضيع الشخص بين الإحالات. لذلك يكون الدمج أو التنسيق الحقيقي، بما في ذلك مشاركة المعلومات الضرورية بموافقة مناسبة، أكثر قيمة من إعطاء قائمة هواتف دون مسؤولية عن إكمال الانتقال.'),

    jsonb_build_object('type','heading','level',2,'text','5. الخدمات منخفضة العتبة: لماذا يسهل الوصول جزءًا من الفعالية؟'),
    jsonb_build_object('type','paragraph','text','قد يفشل تدخل مثبت علميًا إذا كان الوصول إليه صعبًا. مواعيد بعيدة، متطلبات أوراق معقدة، ساعات عمل محدودة، شرط الامتناع قبل الدخول، رسوم لا يستطيع الشخص دفعها، الخوف من الوصمة، أو عدم وجود وسيلة نقل قد تجعل الخدمة موجودة على الورق فقط. الخدمة منخفضة العتبة تحاول تقليل الحواجز غير الضرورية مع الحفاظ على السلامة والجودة. يمكن أن تشمل مرونة في المواعيد، نقاط وصول مجتمعية، ربطًا سريعًا بالعلاج، متابعة بعد الانقطاع، تنسيقًا مع الرعاية الأولية، وإتاحة معلومات بلغة يفهمها الشخص.'),
    jsonb_build_object('type','paragraph','text','سهولة الوصول لا تعني خفض المعايير السريرية. على العكس، النظام الجيد يميز بين الحواجز الإدارية التي يمكن إزالتها وبين التقييمات اللازمة للسلامة. لا يحتاج الشخص إلى إعادة سرد قصته كاملة في كل محطة إذا أمكن نقل المعلومات الضرورية بأمان، ولا ينبغي أن تؤدي عودة للاستخدام إلى طرد تلقائي من برنامج علاجي إذا كان التعديل أو التصعيد أكثر فائدة. الاستمرارية هدف علاجي، وفقدان الاتصال نتيجة يجب أن يحاول النظام منعها وقياسها.'),

    jsonb_build_object('type','heading','level',2,'text','6. دعم الأقران والقيادة المجتمعية دون استبدال المختصين'),
    jsonb_build_object('type','paragraph','text','الأقران ذوو الخبرة المعيشة يمكن أن يساعدوا في بناء الثقة، شرح الخدمات، تقليل العزلة، مرافقة الإحالات، استعادة الاتصال بعد الانقطاع، وإعطاء المؤسسات صورة أكثر واقعية عن الحواجز. توصي الأدلة التشغيلية الحديثة بإشراك المجتمع المتأثر في تصميم الخدمات وتنفيذها وتقييمها. لكن دور الأقران يحتاج حدودًا واضحة وتدريبًا وإشرافًا وحماية من الاستغلال الوظيفي. الدعم بالأقران ليس بديلًا عن التشخيص أو وصف الأدوية أو إدارة الطوارئ عندما تتطلب الحالة مختصًا.'),
    jsonb_build_object('type','paragraph','text','تنجح المشاركة المجتمعية عندما تكون لها سلطة حقيقية على تحسين الخدمة، لا عندما تستخدم كشهادة رمزية. يمكن سؤال المستفيدين: أين نفقد الناس في المسار؟ ما الساعات التي لا تناسبهم؟ ما اللغة التي تجعلهم يشعرون بالإدانة؟ ما الذي يمنع النساء أو اليافعين أو ذوي الإعاقة أو من لا يملكون سكنًا من الوصول؟ ثم تُترجم الإجابات إلى تغييرات قابلة للقياس. هذه الحلقة تحول خبرة الشخص من قصة فردية إلى مصدر لتحسين النظام.'),

    jsonb_build_object('type','heading','level',2,'text','7. الوصمة والحقوق والسلامة المؤسسية'),
    jsonb_build_object('type','paragraph','text','الوصمة ليست مشكلة لغوية فقط؛ يمكن أن تقلل الإفصاح وتؤخر طلب المساعدة وتضعف جودة الرعاية. استخدام عبارات تصف الشخص باضطراب أو حاجة صحية بدل اختزاله في صفة، احترام السرية، تجنب الإذلال، وفصل الرعاية عن العقوبة قدر الإمكان عناصر عملية. كما تحتاج الخدمات إلى سياسات واضحة للعنف والتحرش والاستغلال وحماية البيانات، خصوصًا للأشخاص الذين يعتمدون على آخرين في السكن أو المال أو النقل.'),
    jsonb_build_object('type','paragraph','text','الموافقة والخصوصية تحتاجان تكييفًا للسياق. الأسرة قد تكون عامل حماية قويًا، لكنها ليست دائمًا بيئة آمنة. لا ينبغي مشاركة تفاصيل علاج شخص بالغ مع الأسرة تلقائيًا لمجرد أنها تدفع التكلفة أو توفر السكن، كما لا ينبغي استبعاد الأسرة عندما يريد الشخص دعمها ويكون ذلك آمنًا. الأشخاص ذوو الاحتياجات الخاصة قد يحتاجون تواصلًا ميسرًا أو دعم قرار مع الحفاظ على أكبر قدر ممكن من الاستقلال والاختيار.'),

    jsonb_build_object('type','heading','level',2,'text','8. ما بعد الطوارئ والجرعة الزائدة: الانتقال أهم من ورقة الخروج'),
    jsonb_build_object('type','paragraph','text','لحظة الخروج من الطوارئ بعد جرعة زائدة أو تسمم أو إصابة فرصة مهمة لبناء مسار رعاية. الورقة التي تحتوي اسم عيادة لا تضمن وصول الشخص. من الأفضل أن تتضمن الخطة موعدًا محددًا أو اتصالًا مباشرًا حيث أمكن، مراجعة الأدوية والحالات المصاحبة، تقييمًا لخطر تكرار الحدث، معلومات عن الخدمات المتاحة، وخطة لاستعادة الاتصال إذا فات الموعد. في اضطراب استخدام الأفيونات يجب أن يكون الوصول إلى العلاج المثبت والوقاية من الجرعة الزائدة جزءًا من التفكير المبكر لا خيارًا مؤجلًا حتى حدوث أزمة ثانية.'),
    jsonb_build_object('type','paragraph','text','تقييم نجاح هذا الانتقال يحتاج بيانات. ما نسبة من وصلوا إلى أول موعد؟ كم استغرق الانتظار؟ كم شخصًا بدأ علاجًا مناسبًا؟ كم شخصًا استمر بعد شهر أو ثلاثة؟ هل تكررت زيارات الطوارئ؟ هل توجد فروق كبيرة حسب الجنس أو العمر أو السكن أو المنطقة؟ هذه الأسئلة تكشف ما إذا كان النظام يحمي الناس فعليًا أم يكتفي بتسجيل الإحالة. عندما تظهر فجوة، يجب تحليل نقطة التسرب بدل تفسيرها دائمًا على أنها نقص دافعية لدى الشخص.'),

    jsonb_build_object('type','heading','level',2,'text','9. الفئات والسياقات التي تحتاج تكييفًا'),
    jsonb_build_object('type','heading','level',3,'text','الحمل والمراهقة وكبار السن وعدم استقرار السكن'),
    jsonb_build_object('type','paragraph','text','الحمل وما بعد الولادة يحتاجان تنسيقًا بين علاج اضطراب الاستخدام والرعاية التوليدية والنفسية، وعدم إجراء تغييرات دوائية ارتجالية، وحماية من الوصم الذي قد يمنع طلب الرعاية. المراهقون يحتاجون توازنًا بين السرية والحماية وإشراك الأسرة وفق القانون والمرحلة النمائية. كبار السن قد تكون لديهم أدوية متعددة وأمراض مزمنة وسقوط واضطراب معرفي يغير الخطر. من لا يملك سكنًا مستقرًا قد يحتاج خدمات مرنة وحفظًا آمنًا للأدوية ودعم نقل وربطًا اجتماعيًا؛ خطة تفترض عنوانًا ثابتًا وهاتفًا دائمًا قد تكون غير قابلة للتنفيذ.'),
    jsonb_build_object('type','paragraph','text','السجون وأماكن الاحتجاز والبيئات المغلقة تطرح مخاطر إضافية تتعلق بانقطاع العلاج وفقدان التحمل والانتقال عند الإفراج. يجب التفكير في استمرارية الرعاية قبل الدخول وأثناء الإقامة وبعد الخروج، مع احترام المعايير الصحية والحقوقية. كذلك قد يحتاج الأشخاص ذوو الإعاقة الحسية أو المعرفية أو الحركية إلى وصول فيزيائي ومعلومات ميسرة ودعم تواصل. معيار الجودة هو أن تصل الخدمة إلى الشخص بشروط عادلة، لا أن تطلب من الجميع التكيف مع نموذج واحد.'),

    jsonb_build_object('type','heading','level',2,'text','10. كيف نقيس برنامج خفض الضرر؟'),
    jsonb_build_object('type','paragraph','text','القياس يجب أن يتجاوز عدد الزيارات أو المواد الموزعة. المؤشرات المهمة تشمل الوصول إلى الفئات الأعلى خطرًا، سرعة الربط بالعلاج، الاستمرار في العلاج، تكرار الجرعات الزائدة وزيارات الطوارئ، الفحص والربط بعلاج HIV والتهاب الكبد، الإصابات والعدوى، رضا المستفيدين، فقدان المتابعة، والعدالة في الوصول بين المناطق والفئات. ويمكن إضافة مؤشرات السكن والعمل والصحة النفسية عندما تكون ضمن أهداف البرنامج. كل مؤشر يحتاج تعريفًا ثابتًا وفترة متابعة واضحة حتى لا تتحول الأرقام إلى دعاية.'),
    jsonb_build_object('type','paragraph','text','يجب تفسير الأرقام بحذر. ارتفاع عدد الفحوص قد يعني توسع الوصول لا زيادة المرض، وارتفاع عدد حالات الجرعة الزائدة المبلغ عنها قد يعكس تحسن التسجيل. لذلك تُقرأ المؤشرات معًا ومع معرفة تغير حجم الخدمة والسكان. كما ينبغي أن يشارك الأشخاص المستفيدون في تفسير النتائج؛ قد يفسرون انخفاض الحضور بسبب ساعات غير مناسبة أو خوف من كشف الهوية أو تغير في سوق المواد. القياس الجيد يقود إلى تعديل الخدمة ثم إعادة القياس.'),

    jsonb_build_object('type','heading','level',2,'text','11. خريطة قرار عملية للأسرة والمختص والمؤسسة'),
    jsonb_build_object('type','paragraph','text','إذا كان الخطر فوريًا، تكون الأولوية لخدمات الطوارئ المحلية والتدخل المؤهل. إذا لم توجد أزمة فورية لكن توجد جرعات زائدة سابقة أو استخدام أفيونات أو مواد متعددة، فابحث عن تقييم وخطة وقاية وربط بعلاج مناسب بدل الانتظار. إذا كان هناك حقن أو خطر عدوى، يجب ربط الشخص بخدمات الوقاية والفحص والعلاج دون وصم. إذا كان الشخص غير مستعد للتوقف، يمكن البدء بأهداف سلامة وصحة واتصال بالخدمات. وإذا كان مستعدًا للعلاج، ينتقل مباشرة إلى مسار العلاج المبني على الدليل مع الاحتفاظ بعناصر خفض الضرر التي تقلل المخاطر أثناء الانتقال.'),
    jsonb_build_object('type','paragraph','text','بالنسبة للمؤسسات، يبدأ القرار بخريطة للسكان والمخاطر والخدمات الحالية والفجوات. ثم تحدد نقاط الوصول، آلية الإحالة، المسؤولية بعد الإحالة، التدريب المطلوب، حماية البيانات، مشاركة الأقران، ومؤشرات النتائج. يجب مراجعة السياسات التي تطرد أو تمنع أشخاصًا بسبب عودة للاستخدام إذا كانت لا تخدم السلامة. لا يكفي نسخ نموذج من بلد آخر؛ الإطار يحتاج مواءمة مع القانون المحلي والموارد والثقافة مع الحفاظ على المكونات الأساسية القائمة على الدليل.'),

    jsonb_build_object('type','heading','level',2,'text','12. كيف يتكامل خفض الضرر مع التعافي طويل المدى؟'),
    jsonb_build_object('type','paragraph','text','التعافي يمكن أن يشمل الامتناع وتحسن الصحة والوظيفة والعلاقات والسكن والمعنى الشخصي، ويختلف مساره بين الأشخاص. خفض الضرر يحافظ على فرص الوصول إلى هذه النتائج عبر تقليل الأزمات وفقدان الاتصال. الشخص الذي بدأ بفحص عدوى أو خدمة أقران قد ينتقل لاحقًا إلى علاج دوائي أو نفسي، والشخص في علاج مستقر قد يبقى محتاجًا إلى وقاية من الجرعة الزائدة أو دعم السكن. المنظومة الأقوى لا تجبر المستخدم على اختيار هوية واحدة بين خفض الضرر والتعافي؛ تجعل الخدمات متصلة وقابلة للحركة في الاتجاه الذي يناسب الحاجة.'),
    jsonb_build_object('type','paragraph','text','الهدف النهائي ليس تكثير البرامج المنفصلة، بل تقليل الفجوات بينها. الرعاية الأولية والطوارئ وعلاج الإدمان والصحة النفسية وخدمات العدوى ودعم الأقران والسكن يمكن أن تعمل كشبكة إذا عُرفت المسؤوليات ومسارات الانتقال. عندما لا يستطيع شخص واحد معرفة أين يذهب بعد خطوة أولى، فهذه علامة على مشكلة تصميم. المرجع العربي المفيد يجب أن يشرح هذه المنظومة بوضوح ويترك التفاصيل الفردية للفرق المؤهلة والقوانين المحلية.'),

    jsonb_build_object('type','faq','items',jsonb_build_array(
      jsonb_build_object('question','هل خفض الضرر يشجع على استخدام المخدرات؟','answer','لا. هدفه تقليل الوفاة والمرض والعدوى والإصابات وربط الناس بالخدمات، مع دعم العلاج والامتناع لمن يختارهما. الاعتراف بأن بعض الأشخاص لن يتوقفوا فورًا لا يعني الموافقة على الضرر؛ يعني عدم تركهم بلا حماية حتى يصبح العلاج ممكنًا.'),
      jsonb_build_object('question','هل خفض الضرر بديل عن علاج الإدمان؟','answer','لا. يمكن أن يكون بوابة إلى العلاج وجزءًا منه ومكملًا له. العلاج الفعال لاضطراب استخدام الأفيونات مثلًا يُعد أيضًا مكونًا مهمًا في تقليل المخاطر. الهدف هو استمرار الرعاية عبر مراحل مختلفة بدل الفصل بين البرامج.'),
      jsonb_build_object('question','من يحتاج خطة للوقاية من الجرعة الزائدة؟','answer','تزداد الحاجة عند وجود تاريخ جرعة زائدة، استخدام أفيونات أو مواد متعددة، فترات فقدان تحمل بعد امتناع أو احتجاز أو إقامة، أو انقطاع عن علاج فعال. التقييم الفردي يحدد الخطر والخدمات المناسبة وفق السياق المحلي.'),
      jsonb_build_object('question','ما دور الأسرة في خفض الضرر؟','answer','يمكن للأسرة دعم الوصول إلى الرعاية، تعلم الاستجابة للطوارئ ضمن البرامج المحلية، المساعدة في المتابعة وتقليل الوصمة. لكن المشاركة يجب أن تحترم موافقة الشخص وخصوصيته وأمان العلاقة، ولا تُستخدم الأسرة بدل المختصين في إدارة الحالات المعقدة.'),
      jsonb_build_object('question','لماذا تعد خدمات HIV والتهاب الكبد جزءًا من قطاع الإدمان؟','answer','لأن بعض أنماط الاستخدام، وخصوصًا الحقن، ترتبط بخطر أعلى للعدوى، ولأن الفحص والعلاج والوقاية يمكن دمجها مع خدمات الإدمان. الدمج يقلل ضياع الأشخاص بين الإحالات ويحسن استمرارية الرعاية.'),
      jsonb_build_object('question','كيف أعرف أن برنامج خفض الضرر جيد؟','answer','ابحث عن سهولة وصول عادلة، احترام الحقوق والسرية، ارتباط حقيقي بالعلاج والرعاية الجسدية والنفسية، مشاركة مجتمعية، تدريب وإشراف، ونتائج قابلة للقياس مثل انخفاض الجرعات الزائدة وتحسن الربط بالعلاج والعدوى والمتابعة، لا أرقام نشاط فقط.'),
      jsonb_build_object('question','هل يمكن الجمع بين هدف الامتناع وخفض الضرر؟','answer','نعم. من يريد الامتناع يمكنه أن يحتفظ بخطة تقلل المخاطر أثناء الانتقال أو عند التعثر. خفض الضرر لا يفرض هدفًا بديلًا؛ يحافظ على السلامة واستمرارية الاتصال بينما يعمل الشخص والفريق على أهدافه طويلة المدى.'),
      jsonb_build_object('question','ما الخطوة الأولى إذا كانت الخدمات محدودة في منطقتي؟','answer','ابدأ بتحديد الخطر الأكثر إلحاحًا والجهة الصحية أو الطارئة المحلية المتاحة، ثم اطلب إحالة واضحة إلى علاج الإدمان والرعاية النفسية أو خدمات العدوى بحسب الحاجة. وجود خدمة واحدة موثوقة يمكن أن يكون نقطة دخول لبناء بقية المسار.')
